#include "../src/world_render.h"
#include <stdio.h>
int main(int argc,char **argv){if(argc!=2)return 2;FILE *f=fopen(argv[1],"rb");unsigned char raw[16388];if(!f||fread(raw,1,sizeof raw,f)!=sizeof raw)return 3;fclose(f);TaxiTrig trig;taxi_trig_decode(&trig,raw+4,raw+8196);int x,z,yaw,pitch;while(scanf("%d %d %d %d",&x,&z,&yaw,&pitch)==4){int grid[6];for(unsigned i=0;i<6;i++)if(scanf("%d",grid+i)!=1)return 6;int32_t corners[8][4]={{0}};for(unsigned i=0;i<8;i++)for(unsigned j=0;j<3;j++){int n;if(scanf("%d",&n)!=1)return 4;corners[i][j]=n;}TaxiWorldAsset w={.nx=(uint32_t)grid[0],.nz=(uint32_t)grid[1],.sx=grid[2],.sz=grid[3],.ox=grid[4],.oz=grid[5]};TaxiWorldRenderBounds out;if(taxi_world_render_bounds_corners(&w,(TaxiPoint){x,0,z},yaw,pitch,&trig,corners,&out))return 5;printf("%ld %ld %ld %ld\n",(long)out.min_x,(long)out.min_z,(long)out.max_x,(long)out.max_z);}return 0;}
